INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V-Rally: Championship Edition', 'V-Rally is a rally racing video game released in 1997 and known for its mix of licensed vehicles and varied track conditions. It features 11 official rally cars and more than 40 courses with dynamic weather, terrain, and time-of-day variations. Players can fine-tune vehicle settings such as suspension, gear ratios, and steering before competing across three main modes: Arcade, Championship, and Time Trial. In Arcade mode, players advance through competitions grouped by difficulty, each consisting of four stages. Championship mode presents an eight-race tournament with points awarded for top-three finishes, while Time Trial mode focuses on racing against the clock or another vehicle for the fastest time.' FROM games WHERE igdb_id = 6225 ON CONFLICT (game_id, language_code) DO NOTHING;
