INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KKND: Krush, Kill ''N'' Destroy', 'KKnD, or Krush, Kill ''n'' Destroy is a real-time strategy games in the KKnD series. The game takes place in a post-apocalyptic setting, where two factions are fighting for control over the few natural resources left. Each faction has its own campaign consisting of 15 missions each, and there is also a multiplayer mode which allows up to 6 people to play.' FROM games WHERE igdb_id = 71738 ON CONFLICT (game_id, language_code) DO NOTHING;
