INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreams to Reality', 'Dreams to Reality is a third-person action-adventure game. Players assume the role of protagonist Duncan, and explore surreal dream worlds while attempting to stop an evil group that seeks to control subconscious reality. From a third-person perspective, the player navigates the game world, gathering magic powers and weapons and finding friends.' FROM games WHERE igdb_id = 43742 ON CONFLICT (game_id, language_code) DO NOTHING;
