INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buccaneer', 'Buccaneer is a strategy game following in the footsteps of Sid Meier''s Pirates!. Set during the Age of Sail, you have a choice of six campaigns with varying goals (rescue a relative, get buried treasure, etc.), or you can just engage in standalone ship-to-ship battles.  Good management skills are also required, as you must stock up on supplies and recruit men to join you on your missions.' FROM games WHERE igdb_id = 141845 ON CONFLICT (game_id, language_code) DO NOTHING;
