INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon: Remix RPG Adventure', 'In this "anti-RPG" adventure game notable for parodying and subverting common JRPG conventions, you level up by loving, not fighting. Revive dead animals and bond with everyone around you to obtain the most important thing in the universe — love.' FROM games WHERE igdb_id = 73672 ON CONFLICT (game_id, language_code) DO NOTHING;
