INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twinsen''s Little Big Adventure 2 Classic', 'Here comes the sequel of Twinsen''s Little Big Adventure Classic. After saving the world from the evilish Doctor Funfrock, Twinsen is now ready to face a new threat coming from outer space. Originally released in 1997 as Little Big Adventure 2 and Twinsen''s Odyssey, Twinsen''s Little Big Adventure 2 Classic is an action-adventure game that became an instant classic on PC. This game contains cartoon violence.' FROM games WHERE igdb_id = 79653 ON CONFLICT (game_id, language_code) DO NOTHING;
