INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantis: The Lost Tales', 'Atlantis: The Lost Tales is a fantasy adventure computer game developed by Cryo Interactive and published by DreamCatcher Interactive, and released on September 30, 1997. The game is named after its initial and most important setting, Atlantis. It is the first in a Myst-like series, and is followed by Atlantis II (Beyond Atlantis outside Europe), Atlantis III: The New World (Beyond Atlantis II), Atlantis Evolution and The Secrets of Atlantis: The Sacred Legacy.' FROM games WHERE igdb_id = 2209 ON CONFLICT (game_id, language_code) DO NOTHING;
