INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('goldeneye-007', 1638, '1997-08-23', 88, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa0y2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/t1kgjejfqm6cughelyhe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GoldenEye 007', 'GoldenEye 007 is a first-person shooter based on the 1995 James Bond film. The game features a single-player campaign with 20 missions across multiple difficulty levels, emphasizing stealth, varied objectives and mission-based progression. Players can use a range of weapons and gadgets while navigating diverse environments inspired by the movie. The local split-screen multiplayer mode supports up to four players and offers competitive scenarios such as deathmatch, team modes and character selection from the James Bond universe. The multiplayer component became widely recognized for its influence on console FPS design and is considered a landmark feature of the game.' FROM games WHERE igdb_id = 1638 ON CONFLICT (game_id, language_code) DO NOTHING;
