INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diddy Kong Racing', 'Diddy Kong Racing is set on Timber''s Island and revolves around Diddy Kong and his friends'' attempt to defeat the intergalactic antagonist, a wizarding pig named Wizpig, through winning a series of races. The player can take control of any of the featured characters throughout the game. Diddy Kong Racing features five worlds with four racetracks each, and the ability to drive a car, hovercraft, or pilot an aeroplane.' FROM games WHERE igdb_id = 2723 ON CONFLICT (game_id, language_code) DO NOTHING;
