INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blade Runner', 'Blade Runner is an adventure game with an emphasis on detective work rather than on puzzles. There are very few "real" puzzles in the game, and the gameplay mainly consists of questioning suspects, gathering evidence, etc. There are also some action sequences, and throughout the game the protagonist has the ability to use his gun. The player''s decisions can (and will) influence the outcome of the story, bringing the game to one of the six possible endings.' FROM games WHERE igdb_id = 322 ON CONFLICT (game_id, language_code) DO NOTHING;
