INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thunder-truck-rally', 20131, '1997-07-01', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qmawltdnri4awvoaif8a.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Truck Rally', 'Monster Trucks offers nine rugged off-roaders with which to race across jagged, imposing terrains. Not the only game to twist the racing genre to this end, but as you''d expect from Psygnosis, the quality of presentation is head and shoulders above the rest.  There are two types of courses; circuits offer demanding hilly terrains which can easily trash the vehicle and must be learned intimately. Endurance courses offer greater freedom, with the aim of finding the best route to link eight dispersed checkpoints.  To avoid any disorientation, arrows guide you to the next marker. Each area, be it snowy or volcanic, has characteristic features and hazards, yet this doesn''t stop a repetitive feel developing. The third option is a fun mode, and one you might expect from the developer of Destruction Derby. Players have sixty seconds to take their truck on a car smashing spree.' FROM games WHERE igdb_id = 20131 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 20131 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
