INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Land III', 'Donkey Kong Land III is the last part in the Donkey Kong Land series and was released for the Game Boy by Nintendo in 1997. Fame-and-fortune seekers have flooded Donkey Kong Country in search of the fabled Lost World. Dixie Kong & Kiddy Kong rush through 36 Kong-sized levels of action and adventure. Use your animal friends - Squitter the spider, Squawks the parrot, Ellie the elephant, Enguarde the swordfish and Parry the parallel bird - to help you prove your adventuring skills and find the Lost World before someone else does!' FROM games WHERE igdb_id = 1095 ON CONFLICT (game_id, language_code) DO NOTHING;
