INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Felony 11-79', 'Hit and run, baby! Thrash beach-front property, police cars, glass fronted mini-malls and billboards -- essentially, any and everything goes for the greatest joyride of your life! The mission is grab the goods, destroy what you can and get the heck outta town...fast!' FROM games WHERE igdb_id = 45078 ON CONFLICT (game_id, language_code) DO NOTHING;
