INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('actua-soccer-2', 1993, '1997-10-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yx1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1wbe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Actua Soccer 2', 'Actua Soccer 2 or sometimes Actua Soccer 98 due to its capitalization on the 1998 FIFA World Cup was one of the many football titles released to capitalize on the 1998 World Cup, and once again included national teams, but a more polished engine (optimized in the PC version for 3D graphics cards), (in some versions) the full Italian Serie A league, and a new "scenario" mode assured good sales and mostly positive reviews. It also included a team creator mode, which enabled the player to make up to 128 custom teams. Barry Davies was joined by Trevor Brooking on the commentary, and the game featured England football team captain and striker Alan Shearer not only on the cover, but also providing interviews about the game in the press. Michael Owen and Simon Tracey provided motion capture for the players. The game also featured menu music and a cameo appearance from Welsh rockers, Super Furry Animals, which could only be activated after entering a cheat code. Actua Soccer 2 was also bundled with Creative Technology''s Voodoo 2 graphic cards, which helped to achieve widespread distribution and popularity.' FROM games WHERE igdb_id = 1993 ON CONFLICT (game_id, language_code) DO NOTHING;
