INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klonoa: Door to Phantomile', 'Klonoa: Door to Phantomile is a side-scrolling platform game viewed from a "2.5D" perspective. The player moves the protagonist, Klonoa, along a path in a two-dimensional fashion, but the game is rendered in three dimensions. This allows the path followed to curve and for the player to interact with objects outside of the path.' FROM games WHERE igdb_id = 4959 ON CONFLICT (game_id, language_code) DO NOTHING;
