INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beatmania', 20498, '1997-12-10', 83, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2bz9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8di4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beatmania', 'Beatmania is a rhythm game developed by Konami. It is the first game in the BEMANI series ( which it was named after: BEatMANIa ). It is one of the few music games developed by the internal studio GMD (Game Music Division). Beatmania is played with a controller with one turn table and 5 keys, three white and two black. On the screen you will see bars moving from the top to bottom in columns representing each of the keys and the turntable. When the bars reach the judgement line it is time to scratch. The game contain 7 songs, which is the lowest number ever in the BEMANI franchise.' FROM games WHERE igdb_id = 20498 ON CONFLICT (game_id, language_code) DO NOTHING;
