INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('real-bout-fatal-fury-special', 39521, '1997-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1w2o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3mn3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Bout Fatal Fury Special', 'The supreme trial of strength awaits! 19 of Fatal Fury''s hottest heroes collide! One year since the fearsome conclusion to "Real Bout", the hungry wolves ready themselves for a new battle, "Real Bout Special" - the paramount pugilistic proving ground! The game retains the cast of the original Real Bout, with the addition of Tung Fu Rue, Cheng Sinzan, Laurence Blood and Wolfgang Krauser from Fatal Fury Special, with Krauser serving as the new final boss. Geese Howard, who was killed off in the end of the original Real Bout, appears in this game as a hidden final boss in a special "Nightmare Match" and as an unlockable playable character in the home versions. The game also features hidden "extra" versions of Tung Fu Rue, Billy Kane, Blue Mary, and Andy Bogard, for a total of 23 (24 if counting Geese) characters.' FROM games WHERE igdb_id = 39521 ON CONFLICT (game_id, language_code) DO NOTHING;
