INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Vol. 3', 'The spawning continues as the You Don''t Know Jack series pumps out volume 3. Join your host Cookie ad he takes you on a trivia Tilt-a-Whirl that''s a triple-dip of cheeky hip. YDKJ Volume 3 adds a whole slew of question types into a mind-bending mixture of smart-aleckiness and sassitude.' FROM games WHERE igdb_id = 16783 ON CONFLICT (game_id, language_code) DO NOTHING;
