INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shining-force-iii', 28396, '1997-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co300x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57kx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Force III', 'Shining Force III is a fantasy turn-based tactics role-playing video game designed for the Sega Saturn by Camelot Software Planning. It is a continuation of the Shining series. Comprising three separate but overlapping storylines, the Japanese version of Shining Force III was released in three volumes, known as: "Scenario 1 - God Warrior of the Kingdom", "Scenario 2 - Target: Child of God", and "Scenario 3 - "Bulzome Rising". In America and Europe, only Scenario 1 was released. The real ending to the game can only be viewed by completing all the games in the series.' FROM games WHERE igdb_id = 28396 ON CONFLICT (game_id, language_code) DO NOTHING;
