INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('goal-storm-97', 20141, '1997-05-02', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5fyr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scto3c.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goal Storm ''97', 'Goal Storm ''97 is a slightly improved version of the Japan-exclusive J-League Jikkyō Winning Eleven 97. It features 32 international teams, four different stadiums, 13 team formations, eight unique strategies, and a choice of Exhibition Mode, International League, International Cup, and Penalty Kick mode. It can be played as one or two players. It gained very high reviews, which considered it one of the most playable soccer video games on PlayStation at the time.' FROM games WHERE igdb_id = 20141 ON CONFLICT (game_id, language_code) DO NOTHING;
