INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat 4', 'Mortal Kombat 4 is 1 vs 1 fighting game, similar to the other Mortal Kombat games, but this is first game in series with 3D characters models. The player can choose from 15 different fighters at the start (and several unlockables later on). Many fighters from earlier games in the series make a comeback (like Scorpion, Sub Zero, Liu Kang, Sonya Blade, Johnny Cage etc.) while other new fighters join in, like Shinook (who is the main evil character in this game), Fujin, Jarek, and Kai. Goro returns as a boss.' FROM games WHERE igdb_id = 1622 ON CONFLICT (game_id, language_code) DO NOTHING;
