INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bushido Blade', '"Bushido" is the soul of Japan - an ancient honor code deeply followed by samurai warriors for centuries. Plunge into real world battles across vast 3D environments that you can run, slice and tear through. Sword matches become unbelievably real where one critical blow is the mean difference between death and victory.' FROM games WHERE igdb_id = 1418 ON CONFLICT (game_id, language_code) DO NOTHING;
