INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('warlords-iii-reign-of-heroes', 932, '1997-10-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7a61.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/nx8tiyvkjwzvw9uazcnp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warlords III: Reign of Heroes', 'Warlords III: Reign of Heroes is a turn-based strategy game set in a fantasy universe. The Selentine Empire has been overrun by undead and a number of warlords are fighting to determine who will control what remains of the world. Players must build armies to conquer cities and overwhelm their opponents. The game features 84 different unit types, each of which has different combat strengths, and movement points. Players can use the random map generator to play single games, there are 12 stand-alone game scenarios, plus a campaign mode. Diplomacy is possible and the user can choose from a range of different victory conditions: Last Warlord Standing, Most Cities, Most Victory Points, Most Money.' FROM games WHERE igdb_id = 932 ON CONFLICT (game_id, language_code) DO NOTHING;
