INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed II', 'There are three main game types. The first two are single race and tournament and the last is a knockout race. Single races allow players to become familiar with the circuits and increase their skill of any one of the six tracks. The six tracks are called Mediterranean, Mystic Peaks, Proving Grounds, Outback, North Country, and Pacific Spirit.' FROM games WHERE igdb_id = 91 ON CONFLICT (game_id, language_code) DO NOTHING;
