INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Maker 3: Fairy Tales Come True', 'Princess Maker 3 is the third mainline Princess Maker game. The game was originally released in 1997 and 1998 on PlayStation, Sega Saturn, Dreamcast (later rereleased in 2001 as part of Princess Maker Collection where it was bundled with Princess Maker 2) and Windows. In 2017 the game was released on Steam and Nintendo Switch as Princess Maker ~Faery Tales Come True~ (HD Remake), featuring upscaled graphics, a new UI (as well as the old UI) and more.' FROM games WHERE igdb_id = 43184 ON CONFLICT (game_id, language_code) DO NOTHING;
