INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pilot Brothers', 'The case of the stolen elephant! Elephant... Rare... Striped. ...has been kept for many years by an animal trader named Karbophos. Being unable to overcome abuse, it escaped and found a home at the zoo in our city. This is definitely Karbophos''s work. To the zoo!' FROM games WHERE igdb_id = 25513 ON CONFLICT (game_id, language_code) DO NOTHING;
