INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('international-superstar-soccer-pro-98', 44932, '1997-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y4m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/abq8pp2sysrfj9z3fpjv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Superstar Soccer Pro 98', 'International Superstar Soccer Pro 98, officially abbreviated as ISS Pro 98, is a football simulation game developed and published by Konami for the PlayStation in 1997. It is part of the International Superstar Soccer (ISS) series, known for its focus on realistic gameplay and detailed graphics for the time. ISS Pro 98 features a wide range of national teams, realistic player animations, and improved AI, making it one of the more advanced football games of its era. The game offers various modes, including Exhibition, International Cup, World League, and Training. ISS Pro 98 is often remembered as one of the best football games on the original PlayStation. Despite not having the FIFPro license, the game showcased Italian player Fabrizio Ravanelli on the cover of its PlayStation version. Additionally, the German release featured Andreas Koepke from Germany, and the British release featured Paul Ince.' FROM games WHERE igdb_id = 44932 ON CONFLICT (game_id, language_code) DO NOTHING;
