INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-lost-world-jurassic-park--2', 132135, '1997-09-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2znt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc83bz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost World: Jurassic Park', 'The Lost World: Jurassic Park is a light gun arcade game from Sega. It was released in 1997, and is based on the film of the same name. It is also a sequel to Sega''s 1994 Jurassic Park arcade game. The game features five levels based on environments from the film, including a laboratory and a workers'' village. Four of the levels feature a boss battle that must be won to advance the game. Boss enemies include Tyrannosaurus, Deinosuchus and Carnotaurus. Velociraptors are also featured as enemies throughout the game. Pachycephalosaurus, Compsognathus and venom-spitting Dilophosaurus are also encountered throughout the game. At times, the game presents the player with an opportunity to rescue a human who is being attacked by one or multiple dinosaurs. Saving the human results in the human rewarding the player with either a temporary weapon upgrade or additional health.' FROM games WHERE igdb_id = 132135 ON CONFLICT (game_id, language_code) DO NOTHING;
