INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Shots Golf', 'Everybody''s Golf, known in Japan as Minna no Golf, is the first game in the Everybody''s Golf series. The North American release was renamed Hot Shots Golf. It was the only game in the series to be developed by Camelot Software Planning, which later developed the Mario Golf series.' FROM games WHERE igdb_id = 36665 ON CONFLICT (game_id, language_code) DO NOTHING;
