INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jonah Lomu Rugby', 'Jonah Lomu Rugby is a sports video game developed by Rage Software and published by Codemasters in 1997. It was released for MS-DOS, PlayStation and Sega Saturn. It was the first rugby union game released on the Saturn or PlayStation platforms. It has five game modes: Friendly, World Cup, Tournament, Territories Cup and Classic Matches. The title of the video game refers to former New Zealand winger Jonah Lomu.' FROM games WHERE igdb_id = 2401 ON CONFLICT (game_id, language_code) DO NOTHING;
