INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('grandia', 4127, '1997-12-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coafk6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar46sa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grandia', 'Grandia is a role-playing video game developed by Game Arts and published by Entertainment Software Publishing for the Sega Saturn console as the first game in their Grandia series. Initially released in Japan in 1997, the game was later ported to the PlayStation in 1999, with an English version of the game appearing on the platform in North America in the following September by Sony Computer Entertainment America, and later in Europe in March 2000 by Ubisoft. The game was produced by much of the same staff who worked on the company''s previous role-playing endeavor, the Lunar series, including producer Yoichi Miyagi and music composer Noriyuki Iwadare. Since its release, Grandia has become notable for its combat mechanics, which have been carried over to future games within the franchise, and has spawned two spin-off titles – Grandia: Digital Museum and Grandia: Parallel Trippers – both released exclusively in Japan. In celebration of the announcement of renewing development on Grandia Online, which acts as a prequel to Grandia, the game was re-released on Sony''s PlayStation Network platform in Japan as a downloadable title in April 2009 and in North America on February 25, 2010. It was re-released in Europe on November 10, 2010.' FROM games WHERE igdb_id = 4127 ON CONFLICT (game_id, language_code) DO NOTHING;
