INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blood', 7644, '1997-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2pkw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gpvjao4hdwkum3bwywxu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood', 'You carved your soul to shreds in servitude to a dark god, but false promises and betrayal were your only reward. Now you have a score to settle and it will be measured in blood! Experience the madness in one carnage-soaked package! All the gore, all the unholy war! Zombies, gargoyles, hellhounds and blood-crazed hordes of horrors await! Crush loathsome evil of the mighty Tchernobog! Or condemn yourself to eternal damnation in this leviathan of unhallowed gaming action! Visit a dark near-future world populated by hundreds of bloodthirsty enemies. You''ll engage in a nightmarish battle against the minions of an ancient god bent on wiping humanity from the face of the earth. With cultists, gargoyles, zombies, hellhounds, and an unholy host of other terrors, Blood immerses you in a world of horror unlike any you''ve experienced before.' FROM games WHERE igdb_id = 7644 ON CONFLICT (game_id, language_code) DO NOTHING;
