INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredible Hulk: The Pantheon Saga', 'True to the comic books, the Hulk relies on no other weapons than his massive muscles to punch, kick and crush his enemies. When he has accumulated enough gamma energy, he may use powerful special moves like a Vortex Spin or the Floor Hammer. Rare bonus items also allow the Hulk to summon one of the four Pantheon team members Atalanta, Ulysses, Ajax and Hector to assist in the thick of battle.' FROM games WHERE igdb_id = 45512 ON CONFLICT (game_id, language_code) DO NOTHING;
