INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sentient', 2234, '1997-04-10', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3h5u.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sentient', 'Sentient is a first-person adventure developed by Psygnosis and released on the PlayStation in 1997. It was also released for the PC the same year. Sentient''s main feature is the artificial intelligence controlling multiple individual crew members aboard the station, each with their own assignments and behaviors. You interact with the AI characters through an elaborate parser interface, which allows you to ask them everything from the location of a vital piece of equipment, to their opinion of another member of the crew. To succeed, you must take advantage of the crew''s help through this social system. Through interaction with more than 60 characters and exploration of 200 real-time rendered locations you need to try and save the ship, and yourself. The game automatically randomizes sub-plots so that it will be different every time you play.' FROM games WHERE igdb_id = 2234 ON CONFLICT (game_id, language_code) DO NOTHING;
