INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nagano-winter-olympics-98', 3546, '1997-12-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39vf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nagano Winter Olympics ''98', 'The Nagano Winter Olympic Games are here! Experience all of the thrills, spills and "chills" as you compete for glory against the rest of the world. It''s time to find out what you''re made of...Can you bring home a medal? 12 exciting Olympic events! 16 different countries! 1-4 player action. Set new world records and save them to your Controller Pak. Real-time motion captured athletes.' FROM games WHERE igdb_id = 3546 ON CONFLICT (game_id, language_code) DO NOTHING;
