INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beast-wars-transformers', 8018, '1997-12-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zxp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9ivw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beast Wars: Transformers', 'In BEAST WARS you travel along the planet''s surface and explore many areas, looking to destroy any enemies that cross your path. The innovative auto-targeting system locks on to any enemies in your area and makes for some straightforward killing. However, don''t think it''s going to be easy, as you will have to dodge enemy gunfire at the same time. Eventually, your character will use up his Energon supply and you will have to refuel by transforming into Beast mode. While in Beast mode you cannot attack, and your sole purpose is to find power-ups to restore your Energon. BEAST WARS offers 10 different transformers to choose from, each with their own traits. You''ll also have the chance to battle in four different environments, each having its own set of enemies. With 24 missions to play and eight bonus missions, you''ll have plenty to keep you occupied.' FROM games WHERE igdb_id = 8018 ON CONFLICT (game_id, language_code) DO NOTHING;
