INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby''s Dream Land 3', 'That mean old King Dedede is at it again! He''s causing his mischief and Dreamland''s in trouble! Kirby, the resident hero of Dreamland, sets out to teach Dedede a lesson, this time with the help of many of his good friends! But wait! Something''s wrong! Dedede doesn''t seem to be himself... Looks like Kirby has to stop Dedede and find out what is wrong with him! It almost seems like something''s controlling him...' FROM games WHERE igdb_id = 3720 ON CONFLICT (game_id, language_code) DO NOTHING;
