INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vampire-savior-2-the-lord-of-vampire', 39696, '1997-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xrk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vampire Savior 2: The Lord of Vampire', 'Released in Japan in 1997, Vampire Savior 2 was released along side Vampire Hunter 2 and uses the same gameplay mechanics as Vampire Savior. The game adds Night Warriors: Darkstalkers'' Revenge characters Donovan Baine, Huitzil and Pyron to the Vampire Savior cast while omitting Jon Talbain, Rikuo (Aulbath), and Sasquatch. Although the game was never officially released in arcades outside of Japan, the game was incorporated into Darkstalkers 3 and later as its own standard game in the Japanese only release of Vampire: Darkstalkers Collection.' FROM games WHERE igdb_id = 39696 ON CONFLICT (game_id, language_code) DO NOTHING;
