INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Yoda Stories', 'Grab your lightsaber and get ready for terrific Star Wars adventuring in Yoda Stories, the newest in a series of easy-to-play Desktop Adventures from LucasArts. Join Luke Skywalker as he trains to become a Jedi with Yoda, then harness the Force and cross the galaxy to meet exotic aliens, collect stange devices and weapons and deal the Galactic Empire one crippling blow after another - all within an hour!' FROM games WHERE igdb_id = 155 ON CONFLICT (game_id, language_code) DO NOTHING;
