INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crow: City of Angels', 'The Crow: City of Angels is a 3D fighting game in which the player wanders from screen to screen, fighting everybody they come across with a wide variety of kicks and punches that vary based on your proximity to your foe. There is also a large range of weapons including pistols, shotguns, knives, pool cues, pipes and steel drums.' FROM games WHERE igdb_id = 8538 ON CONFLICT (game_id, language_code) DO NOTHING;
