INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Live 98', 'NBA Live 98 is a basketball video game based on the NBA and the fourth installment of the NBA Live series. The cover features Tim Hardaway of the Miami Heat. The game was developed by EA Sports and released on November 30, 1997 for the PlayStation, October 31, 1997 for the PC and December 31, 1997 for the Sega Saturn. It was the final version of NBA Live released for the Super NES, Genesis and Sega Saturn.' FROM games WHERE igdb_id = 26013 ON CONFLICT (game_id, language_code) DO NOTHING;
