INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom 64', 'You killed the Demons once, they were all dead. Or so you thought... A single Demon Entity escaped detection. Systematically it altered decaying, dead carnage back into grotesque living tissue. The Demons have returned - stronger and more vicious than ever before. You mission is clear, there are no options: kill or be killed!' FROM games WHERE igdb_id = 3471 ON CONFLICT (game_id, language_code) DO NOTHING;
