INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Superstar Soccer 64', 'Are you ready for the most realistic soccer game the world has ever seen? Get ready for: Incredible, seemless game control; Awesome animation with over 17,000 motion captured animations; Live, intelligent commentary; Every conceivable soccer move from headers to heel passes; Multiple formations to team strategies; Trade & create your own players; 36 International teams with 16 players per team. Everything a soccer fan wants!' FROM games WHERE igdb_id = 3516 ON CONFLICT (game_id, language_code) DO NOTHING;
