INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-mario-64-shindou-pak-taiou-version', 132642, '1997-07-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5y6k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gf0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario 64: Shindou Pak Taiou Version', 'This version of Super Mario 64, originally released only in Japan, is an enhancement over the International release of the game, as it retains all of the glitch fixes as well as graphical and sound changes. The main differences of this version are the Rumble Pak support, some small glitch fixes, the most notorious being the removal of the backwards long jump, a very important technique for the speedrunning scene, and a new title screen easter egg. This version would later be released on the iQue Player in China (without Rumble support), on the Japanese Wii and Wii U Virtual Console. It was finally localized and released internationally as part of Super Mario 3D All-Stars (under the name of "Super Mario 64"), with small visual enhancements.' FROM games WHERE igdb_id = 132642 ON CONFLICT (game_id, language_code) DO NOTHING;
