INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lands of Lore: Guardians of Destiny', 'In Lands of Lore: Guardians of Destiny you enter a world of intense beauty and mortal danger where your slightest move can trigger cataclysmic events, miraculous escapes, or lethal battles. See magical cities rise out of great oceans. Enter the musty caverns of Dracoid ruins. Discover gruesome altars and witness secret ceremonies never before seen by humans.' FROM games WHERE igdb_id = 2494 ON CONFLICT (game_id, language_code) DO NOTHING;
