INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Fox in "Dry Cereal"', 'The super-suave agent, SPY Fox, must find Mr. Udderly, rescue all the cows, and stop William the Kid from depleting the worlds supply of milk. Using ingenious SPY gadgets, keen wits, and daring moves, SPY Fox, jumps out on an udderly exhilarating adventure!' FROM games WHERE igdb_id = 5204 ON CONFLICT (game_id, language_code) DO NOTHING;
