INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Riven: The Sequel to Myst', 'Riven: The Sequel to Myst is a graphic adventure puzzle game developed by Cyan and released in 1997. It continues the story of Myst, following the player’s journey to rescue Atrus’s wife, Catherine, from a decaying world. The game features pre-rendered environments with complex, interconnected puzzles and minimal direct guidance. Its visuals, sound design, and world-building were praised for their depth and realism. Riven expanded on Myst’s narrative and gameplay scale, becoming one of the most acclaimed adventure games of its time.' FROM games WHERE igdb_id = 238 ON CONFLICT (game_id, language_code) DO NOTHING;
