INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Liberation: Warhammer Epic 40,000', 'SSI, the masterminds behind the Five Star General Series’, bring their Midas touch to the Warhammer 40,000 world in the first ever video-game adaption of the Epic table-top game. With over 85 unit types, this addition to the 40k franchise brings the vastness and depth of an Epic-style battle to your PC, allowing you greater selection and customisation over your army. This, along with the multiple scenarios and battlefronts to fight from, will keep your strategic mind on edge for hours on end.' FROM games WHERE igdb_id = 12521 ON CONFLICT (game_id, language_code) DO NOTHING;
