INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-bomberman-5', 38387, '1997-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w8i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8o42.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Bomberman 5', 'An evil Bomber named Emperor Terrorin who has the power of Time itself has freed various criminal Bombers from their prison cells in orbit around Planet Bomber. Setting them up in a warped time and space, Shirobon, Kurobon, and their Louie (Rui) companions must travel through stages and defeat them before going up against Emperor Terrorin himself. Super Bomberman 5, released by Hudson Soft in early 1997, was the final Bomberman game released on the Super Family Computer - the Japanese version of the SNES. The game was released in two variations: a standard cartridge and a gold cartridge, which was sold exclusively through CoroCoro Comic. The gold cartridge included extra maps in battle mode.' FROM games WHERE igdb_id = 38387 ON CONFLICT (game_id, language_code) DO NOTHING;
