INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-granstream-saga', 19156, '1997-11-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66ib.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclfpd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Granstream Saga', 'The Granstream Saga is an action game with strong RPG elements, and a spiritual successor to Gaia games. The player controls Eon as he explores overworld and dungeon locations, which are presented in overhead-viewed 3D. Battles are one-on-one; whenever an enemy is encountered, the view is zoomed on the combat participants who must fight each other until one of them emerges victorious. Eon can use swords, daggers, or axes against his enemies. He has a variety of attack moves at his disposal, including combos, shield-breaking abilities, etc.; he can also actively guard and cast magic spells. Leveling up, which increases Eon''s attributes, occurs at set intervals throughout the game rather than from accumulating experience points.' FROM games WHERE igdb_id = 19156 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 19156 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
