INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fragile Allegiance', 'Assemble your fleets, fill your silos with nuclear warheads, conduct research, gather resources, and wage war in a vast galaxy in this unique take on 4X Strategy. Appoint Colony Supervisors to manage your colony and deploy Spy Satellites for the ultimate in skulduggery. Negotiate and trade with 6 different alien cultures, each with their own unique personality.' FROM games WHERE igdb_id = 2619 ON CONFLICT (game_id, language_code) DO NOTHING;
