INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wayne Gretzky''s 3D Hockey ''98', 'Take on "The Great One" again in this hot sequel to the smash hit voted "Best Sports Game" of ''96! With more great features, such as new hidden teams and improved, hard-hitting AI, Gretzky ''98 packs a wallop! Includes all 26 teams, each with 17 available players on their actual NHL teams, and you can make player trades or line manipulations to create a powerhouse team of your own. Play 3-on-3, 4-on-4 or 5-on-5 games on either arcade or regulation size hockey rinks, plus exhibition games, full 82 game seasons or a best-of-seven playoff series with full statistic saving capability.' FROM games WHERE igdb_id = 3631 ON CONFLICT (game_id, language_code) DO NOTHING;
