INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strikers 1945 II', 'Continuing where the last game ended, the forces of CANY had been demolished by the previous Strikers'' line-up. However, a small group known as the FGR stole the sources and technology responsible for the last events and planned to continue CANYs work by initiating world-warfare with massive mech technology. Once again, the Strikers are called into action.' FROM games WHERE igdb_id = 39299 ON CONFLICT (game_id, language_code) DO NOTHING;
