INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('imperium-galactica', 15188, '1997-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2a4q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4spd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Imperium Galactica', 'We are in the year 2300. The Galactic Empire, formed by the human species in the known universe, eventually split into numerous factions, seven alien races and two empires of renegade humans. One of the most dangerous, the Darglans threaten the coexistence and peace established between the various species. It is time to face the threat and stop the expansion. You start out as a young lieutenant and are given a series of missions to complete. You then advance to the next rank and are given more ships to control and more available commands, but you have more area of the universe to police and more colonies. This continues until you reach the rank of Grand Admiral, where you are able to view the whole map.' FROM games WHERE igdb_id = 15188 ON CONFLICT (game_id, language_code) DO NOTHING;
