INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lost Vikings 2', 'Will the Vikings find their way home across time and space? Will Erik lead his brothers to safety without bonking himself back into thinking he''s an iguana? Will Olaf be reunited with his wife and daughters? Will Baleog ever to get a date with Freya, that Valkyrie babe on the "Resume Game" screen? Stay tuned...' FROM games WHERE igdb_id = 1253 ON CONFLICT (game_id, language_code) DO NOTHING;
