INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-reign-the-future-of-war', 659, '1997-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yh5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Reign: The Future of War', 'Dark Reign narrowly beat Total Annihilation as the first RTS to incorporate 3D movement and positioning. This increases the strategic advantage of hills and mountains. Each mission puts you in the role of commander of either the Imperial army or the Freedom fighters in a campaign to undermine and eventually destroy the opposing force. This game has many unusual features for the RTS genre. AI patterns you to simply give a unit the order "Search and Destroy" and it would drive off towards the enemy''s last known location, in search for something to kill. There is also "explore" mode which let your units do all the map exploring for you. A mission/campaign editor is also provided.' FROM games WHERE igdb_id = 659 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 659 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
