INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: X-Wing vs. TIE Fighter', 'Star Wars: X-Wing vs. TIE Fighter is the third release of the X-Wing computer game series. The player has the ability to choose for each mission which squadron he or she wants to fly in (e.g. either the Y-wings that disable a ship for capture or the X-wings that support them), his or her specific ship type, and the ship''s armaments.' FROM games WHERE igdb_id = 170 ON CONFLICT (game_id, language_code) DO NOTHING;
