INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Masters of Teräs Käsi', 'Star Wars: Masters of Teräs Käsi is a fighting game released for PlayStation. The 3D fighting genre fulfills its ultimate destiny with Star Wars Masters of Teräs Käsi, an intense one-on-one combat experience for the Sony PlayStation. The story revolves around the mysterious Arden Lyn, a master of the ancient art of Teräs Käsi, as she leads a group of the most feared champions of the Galactic Empire to eliminate the leaders of the Rebel Alliance. Join Luke Skywalker, Han Solo, Boba Fett, Princess Leia, Chewbacca, plus a few surprise characters in a Star Wars environment like you''ve never experienced.' FROM games WHERE igdb_id = 18044 ON CONFLICT (game_id, language_code) DO NOTHING;
