INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chameleon Twist', 'Chameleon Twist is a 3D-Jump & Run, developed by Japan System Supply and released by Sunsoft in 1997. After following a rabbit into a magical hole in the ground, the blue chameleon named Davy realises that he has taken on a humanoid form. In an attempt to find a way back home, Davy is traveling throughout six lands with his friends, Jack, Fred, and Linda; together they discover Jungle Land, Ant Land, Bomb Land, Desert Castle, Kids Land, and Ghost Castle to find the certain magic portal.' FROM games WHERE igdb_id = 3427 ON CONFLICT (game_id, language_code) DO NOTHING;
