INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('magic-the-gathering', 12443, '1997-02-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2err.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sztnt0dbzrrj7pkcd1bn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic: The Gathering', 'Magic: The Gathering is a computer game published by MicroProse in April 1997 based on the collectible card game Magic: The Gathering. The game takes place in the plane of Shandalar, where the player must travel the land and fight random enemies to gain cards, and defeat five wizards representing the five colors. The player must prevent one color from gaining too much power, and defeat the planeswalker Arzakon, who has a deck of all five colors. Adventure game and role-playing game elements are present, including inventory, gold, towns, dungeons, random battles, and character progression in the form of new abilities and a higher life point total. An oversized version of Aswan Jaguar was included in the game box.' FROM games WHERE igdb_id = 12443 ON CONFLICT (game_id, language_code) DO NOTHING;
