INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-COM: Apocalypse', 'Your mission, as X-COM Commander, is to combat alien aggression and uncover their deadly intentions. But Beware! Alien infiltration into the city and its politics could see you under fire from criminal gangs, religious sects, and even the police! Alien fleets fill the skies, creatures terrorise the city, chaos reigns... Welcome to the war, welcome to the Apocalypse.' FROM games WHERE igdb_id = 26 ON CONFLICT (game_id, language_code) DO NOTHING;
