INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VooDoo Kid', 'VooDoo Kid is a Windows PC Adventure game. "Who’d have thought it? Who could possibly have imagined it? A kid, a kid just like any other. A tired little boy reading his book. A tired little boy… so tired… then wide awake and all alone… A prisoner of the unfriendly, unearthly Baron Saturday, king of the Zombies, master of the Voodoo Cult and lord of poor Kid’s shaky future..."' FROM games WHERE igdb_id = 78413 ON CONFLICT (game_id, language_code) DO NOTHING;
