INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('colony-wars', 8280, '1997-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23s8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/o5y8lzlx7cals1hruiqi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colony Wars', 'Colony Wars is a combat fighter game set in space. You, as the player, join as a recruit in the League''s fleet. Missions take place in various fighters, from a 1st person view inside the cockpit, or a 3rd person view from behind your ship. Ships have separate meters for shields and armor, and the player must cycle between weapons designed specifically to damage each. At the most basic, purple lasers must drain a target''s shields, followed by switching to red lasers to destroy them.  The game features advanced lighting and particle effects for the Playstation, as well as a basic simulation of Newtonian physics. Thrusters are only active for as long as the accelerate button is held down. The player can burst fire their thrusters and drift, allowing for some advanced maneuvers. The campaign also features multiple endings and branching missions/storylines, based on your performance in the previous operations.' FROM games WHERE igdb_id = 8280 ON CONFLICT (game_id, language_code) DO NOTHING;
