INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dark-earth', 18137, '1997-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j6j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpt5t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Earth', 'Dark Earth is a post-apocalyptic action-adventure game for the PC. Dark Earth takes place several centuries in the future, when a meteor collision with Earth tossed up great clouds of dust that blocked out the sun. Earth''s remaining survivors began to seek refuge beneath small openings in the clouds, the few places light could be found. Those that remained in the ''dark earth'' were hunted by strange creatures, infected with the darkness. To shelter themselves from the dangerous ''dark earth'', the people began to form cities beneath the light called ''Stallites''. At the time of the game, most of the citizens of the stallite have forgotten their history and now worship the light as a god. The stalites are run by ''Sun Priests'', who maintain order and prevent the creatures of darkness from harming the city. The game follows the story of Arkhan, a "guardian of fire", protector of the stallite ''Sparta'' and the Sun Priests. After an attack on the sun priests, Arkhan has a poison thrown into his face that begins to infect him with the dark sickness. He begins to mutate into a creature of the dark and has to find a cure before his transformation is complete. Along the way, he is treated as an enemy by most of his former friends while he struggles to uncover the conspiracy behind the attack.' FROM games WHERE igdb_id = 18137 ON CONFLICT (game_id, language_code) DO NOTHING;
