INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outlaws', 'Outlaws is a first-person shooter released by LucasArts in 1997. It uses a Wild West setting. It follows retired U.S. Marshal James Anderson, who seeks to bring justice to a gang of criminals who killed his wife and kidnapped his daughter. The game is a first-person shooter. Players control the character as he utilizes several American Old West weapons and items, such as a rifle, shotgun, dynamite and revolver. The player can activate the lantern inventory item to lighten dark areas, and use a shovel in specific areas to dig holes.' FROM games WHERE igdb_id = 196 ON CONFLICT (game_id, language_code) DO NOTHING;
