INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Tough and the Night of Roasted Moths', 'What do alien abductions, a depressed town, and a purple tapir named Pentagruel have in common? Can a bumbling gumshoe make his stolen candy theory stick? Find out with the "Sherlock Gnome" of detectives, Tony Tough, and a hilarious cast of characters as he cracks the case on the most adventurous and comical night of his life!' FROM games WHERE igdb_id = 10792 ON CONFLICT (game_id, language_code) DO NOTHING;
