INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VR Baseball ''97', 'VR Baseball ''97 invites players to immerse themselves into the world of baseball by selecting from a variety of teams, stadiums, and players. Designed to be the first baseball game that lets you play in a real-time 360-degree 3D world, gamers can play any position and watch the game play out from any angle. The game includes 700 players, 28 stadiums, all-star games, national anthems, and statistics for the 1997 baseball season. Gamers may play alone or challenge a friend to an "Exhibition Game," or a "Home Run Derby."' FROM games WHERE igdb_id = 20819 ON CONFLICT (game_id, language_code) DO NOTHING;
