INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trash It', 'Trash It is an orgy of destruction that will set pulses racing in the most original arcade in recent years. Based on the exploits of Jack Hammer, Trash It offers the player the opportunity to destroy memmoth buildings, monumental structures and pulsating power plants in the ultimate frency of devastation and vandalism. Your palms will sweat, your veins bulge as you go through level after level of challenging gameplay.' FROM games WHERE igdb_id = 46492 ON CONFLICT (game_id, language_code) DO NOTHING;
