INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rally Cross', 'Rally style racing lets you perform power slides, end-over-end crashes, rolling your car, crashing into others and forcing cars off the road -- everything damages your vehicle! Compete in a season or tournament mode with three difficulty levels and four perspectives. So what are you waiting for? Rally on!' FROM games WHERE igdb_id = 8647 ON CONFLICT (game_id, language_code) DO NOTHING;
