INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shipwreckers!', 'Shipwreckers is a third-person arcade-style shooter where you sail around in a pirate ship battling other pirate vessels and destroying the gun turrets and flamethrowers that are defending ports in an attempt to spread your swashbuckling reign of terror. Reward treasures and increasingly more potent weapons keep the pacing alive in this near top-down 3D action game. Shipwreckers supports solo play, head to head, and multi-person battles.' FROM games WHERE igdb_id = 7664 ON CONFLICT (game_id, language_code) DO NOTHING;
