INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mortal-kombat-mythologies-sub-zero', 1610, '1997-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y23.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc81gy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat Mythologies: Sub-Zero', 'Mortal Kombat Mythologies: Sub-Zero is a story-driven fighting game that casts you in the shoes of Sub-Zero, and chronicles a series of events that occurred prior to Mortal Kombat 1. It is the first Mortal Kombat game to feature side-scrolling gameplay. Gameplay wise the game takes the Mortal Kombat familiar 2D fighting environment and turns it into a hybrid fighter/platformer game, where you must travel trough hazardous levels running and jumping around as well as fighting your way against both digitized and polygonal enemies. Sub-Zero''s interface is the same as in every MK game, with the addition of a "use" and "turn around" buttons and additions such as an inventory, and a slight RPG twist in which you get exp. for defeating opponents, which translates into new techniques and moves to execute in the game.' FROM games WHERE igdb_id = 1610 ON CONFLICT (game_id, language_code) DO NOTHING;
