INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('janken-game-acchi-muite-hoi', 269938, '1997-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coad59.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scyt00.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Janken Game Acchi Muite Hoi!', 'A Janken (rock-paper-scissors) simulator based off the Acchi Muite Hoi! variation of the game, where the player must win a Janken match then correctly guess which direction their opponent will look. The game''s cabinet utilizes a unique control setup, with a large joystick with two buttons on it; holding both buttons chooses rock, a single button chooses scissors, and no buttons held chooses paper. The player can pick between four different opponents, with a meter at the top of the screen filling up whenever the player guesses the opponents moves right. Once the meter is full the opponent is defeated and the next in line challenges the player.' FROM games WHERE igdb_id = 269938 ON CONFLICT (game_id, language_code) DO NOTHING;
