INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('need-for-speed-v-rally', 72073, '1997-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2095.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: V-Rally', 'V-Rally is a rally racing game initially developed by Eden Studios for the PlayStation, published in North America by Electronic Arts under the title of Need for Speed: V-Rally. Later ported to PC, N64, Game Boy, and Game Boy Color. It features 11 official rally cars and more than 40 courses with dynamic weather, terrain, and time-of-day variations. Players can fine-tune vehicle settings such as suspension, gear ratios, and steering before competing across three main modes: Arcade, Championship, and Time Trial. In Arcade mode, players advance through competitions grouped by difficulty, each consisting of four stages. Championship mode presents an eight-race tournament with points awarded for top-three finishes, while Time Trial mode focuses on racing against the clock or another vehicle for the fastest time.' FROM games WHERE igdb_id = 72073 ON CONFLICT (game_id, language_code) DO NOTHING;
