INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Rally Championship', 'International Rally Championship is a rally computer game which is part of the Rally Championship series. The game was released for Windows in 30 June 1997. It is developed by Magnetic Fields and published by Europress. Several different front covers were released for the game. The game is a sequel to the 1996 version of Network Q RAC Rally Championship. It would in turn be succeeded in 1999 by Mobil 1 Rally Championship.' FROM games WHERE igdb_id = 50210 ON CONFLICT (game_id, language_code) DO NOTHING;
