INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Yumejikuu: Phantasmagoria of Dim. Dream', 'This game is a vertical danmaku shooting game, where two characters engage in danmaku gameplay within individual and separate play areas (aka. split-screen). Upon meeting certain conditions, players are able to unleash a variety of character-specific Spell Attacks upon their opponents in an attempt to whittle down their remaining health points. In Story Mode, the player will face nine opponents, each more capable than the previous. Phantasmagoria of Dim.Dream also features a Match Play Mode where the player may face off against AI opponents or compete against other players, as well as watch AI vs. AI matches.' FROM games WHERE igdb_id = 45965 ON CONFLICT (game_id, language_code) DO NOTHING;
