INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('magic-the-gathering-battlemage', 84256, '1997-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ert.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scary0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic: The Gathering - Battlemage', 'Magic: The Gathering: BattleMage is a real time strategy game published in January 1997 by Acclaim for both PCs and PlayStation. It was also in development for the Sega Saturn, but this version was cancelled in mid-1997. In addition to the real time strategy game, BattleMage has a head-to-head mode. It is set on the continent of Corondor, where a planeswalker named Ravidel forces the most powerful mages to fight each other, so that he can eventually destroy them and conquer the land. The game had a poor critical reception due to its unfair AI, unfriendly interface, and unbalanced gameplay.[citation needed] Spectrum Holobyte filed a lawsuit after Acclaim published the PC version in January 1997, claiming Acclaim had violated an agreement the two companies made in November 1996 which established a release schedule for the game, with the two companies publishing it for different platforms. In October of 2018, the game''s rights were acquired by Canadian production company Liquid Media Group along with other titles originally owned by Acclaim Entertainment.' FROM games WHERE igdb_id = 84256 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 84256 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
