INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Helix', 'Broken Helix is a third-person shooter game developed and published by Konami for the PlayStation in 1997. The game boasts "4-D" real time gameplay, allowing the player to activate and deactivate certain objects in later levels of the game. It also has four plot lines, allowing the player to finish the game in four different ways.' FROM games WHERE igdb_id = 19996 ON CONFLICT (game_id, language_code) DO NOTHING;
