INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roly-Polys no Nanakorobi Yaoki', 'Roly-Polys Nanakorobi Yaoki is a children''s edutainment game by musician and multimedia artist Osamu Sato''s studio OutSide Directors Company. Its cast of eight characters, the Roly-Polys, teach children about topics like history and the alphabet through music and 3D animation.' FROM games WHERE igdb_id = 123288 ON CONFLICT (game_id, language_code) DO NOTHING;
