INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soviet Prisoner', 'You are Lieutenant Klaus von Steinfeld of the 6th German Army. During the Stalingrad Offensive, you have been captured by the red army and deported to a secret prison in Western Siberia. You must try to escape from this heavily guarded prison or get over it to give to the enemy, thereby risking the death penalty.' FROM games WHERE igdb_id = 135346 ON CONFLICT (game_id, language_code) DO NOTHING;
