INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Moto 2', 'Jet Moto 2 is the sequel to the 1996 game Jet Moto. Gameplay in the Jet Moto series differs from traditional racing games, as players instead control hoverbikes which hover close above the ground and can be driven over both land and water. Most of the courses in the games are designed to take advantage of this ability.' FROM games WHERE igdb_id = 45214 ON CONFLICT (game_id, language_code) DO NOTHING;
