INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pajama Sam''s Sock Works', 'Climb in and help Pajama Sam control the Sock-O-Matic Mark III, the sock-sorting dream machine the makes chores fun! Concentration is the key as Sam tries to control that crazy contraption. Chutes, pushers, slides, and swing arms are just a few of the gadgets you''ll need to guide Sam''s socks into the baskets. The Sock-O-Matic even has a Custom Level Builder that allows kids to create their own puzzling levels!' FROM games WHERE igdb_id = 10652 ON CONFLICT (game_id, language_code) DO NOTHING;
