INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost in the Shell', 'This is a cyberpunk-themed third-person shooter video game developed by Exact and Production I.G for the PlayStation. The game plot revolves around a recruit of Public Security Section 9 as he investigates and combats the Human Liberation Front. The player controls a Fuchikoma, a robotic fighting vehicle capable of traversing walls and ceilings.' FROM games WHERE igdb_id = 8336 ON CONFLICT (game_id, language_code) DO NOTHING;
