INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Culdcept', 'In Culdcept you are a Cepter, a powerful magic summoner who uses cards that are fractions of the creator goddess Culdra. You collect cards by beating other powerful Cepters in battles on table-top style game boards. If you win, your reward is to create a new world under Culdra and become a new god.' FROM games WHERE igdb_id = 78415 ON CONFLICT (game_id, language_code) DO NOTHING;
