INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Crisis II', 'Time Crisis II is a light gun arcade game and the second installment in the Time Crisis series. It introduces co-operative multiplayer to the franchise. The game was first released in arcades in April 1998, with an enhanced port released on the PlayStation 2 in October 2001, bundled with the GunCon 2 controller.' FROM games WHERE igdb_id = 13893 ON CONFLICT (game_id, language_code) DO NOTHING;
