INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ignition', 7139, '1997-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2a4b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1zkr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ignition', 'Ignition is an action packed racing game viewed from above and slightly behind the player. The cars on offer range from police car and VW Beetle to school bus and truck, each of which has its own strengths and weaknesses - trying to win with the bus, which involves blocking everyone behind the hideously slow vehicle for 3 laps, is perhaps the ultimate challenge. Initially there are 5 tracks available, with practice and single race modes as well as full championship at 3 levels - winning each of the first 2 levels unlocks an extra track. They all have hazards running through them, and sections where you must make a split-second choice between the safer route and the risky but potentially rewarding one. Multiplayer can be done via network or by split-screen - in a break with convention the screen is split vertically rather than horizontally.' FROM games WHERE igdb_id = 7139 ON CONFLICT (game_id, language_code) DO NOTHING;
