INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('7th-legion', 9895, '1997-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2zpg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21lz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7th Legion', 'There''s no Salvation from this army! Can you survive this furiously fast, kill-for-money, real-time blood-fest? There''s nowhere to hide as you smash your opponent in ''to-the-limit'' conflict. And, while you''ve got a few nanoseconds to spare, you''ve got to build to survive, mechs, tanks, troops, mounted slavens - a host of murderous military units who will hone their killing skills with experience. Just what devastating effect does a 7th legion priest have in battle? what happens when you summon the dark legion? The landscape is isometric and you''ve got to be ice-cool to survive in the blazing heat of combat. And there''s more! Random power ups and a massive selection of battle cards that can turn the tides of war in a flash. But be careful: you don''t know what cards your opponent is holding and even when you''ve got his last trooper cornered he might play the battle card that wipes away your entire force! Salvation? They''ll be lucky to find a stone to crawl under!' FROM games WHERE igdb_id = 9895 ON CONFLICT (game_id, language_code) DO NOTHING;
